effect.shader:
float gmHash2(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmVnoise(vec2 p){
vec2 i = floor(p); vec2 f = fract(p);
f = f * f * (3.0 - 2.0 * f);
return mix(mix(gmHash2(i), gmHash2(i + vec2(1.0, 0.0)), f.x),
mix(gmHash2(i + vec2(0.0, 1.0)), gmHash2(i + vec2(1.0, 1.0)), f.x), f.y);
}
float gmLum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
void main(){
vec2 uv = acScreenNorm;
vec2 px = 1.0 / getTexSize(inputImg.size);
float aspect = max(getTexSize(inputImg.size).x / max(getTexSize(inputImg.size).y, 1.0), 0.5);
vec2 np = uv * vec2(6.0 * grainScale, 6.0 * grainScale / aspect);
float nx = gmVnoise(np + vec2(acTime * 0.02, 0.0));
float ny = gmVnoise(np * 1.3 + vec2(0.0, acTime * 0.02) + 3.7);
vec2 wuv = uv + (vec2(nx, ny) - 0.5) * bleedAmt * 0.012;
vec3 c = texture2DCv(inputImg.texture, clamp(wuv, 0.0, 1.0)).rgb;
if (washSoft > 0.01) {
vec3 acc = c * 2.0;
acc += texture2DCv(inputImg.texture, clamp(wuv + vec2(px.x * 1.5, 0.0), 0.0, 1.0)).rgb;
acc += texture2DCv(inputImg.texture, clamp(wuv - vec2(px.x * 1.5, 0.0), 0.0, 1.0)).rgb;
acc += texture2DCv(inputImg.texture, clamp(wuv + vec2(0.0, px.y * 1.5), 0.0, 1.0)).rgb;
acc += texture2DCv(inputImg.texture, clamp(wuv - vec2(0.0, px.y * 1.5), 0.0, 1.0)).rgb;
c = mix(c, acc * 0.1667, washSoft);
}
float l = gmLum(c);
c = clamp(mix(vec3(l), c, pigmentSat), 0.0, 1.0);
float l0 = gmLum(texture2DCv(inputImg.texture, clamp(wuv, 0.0, 1.0)).rgb);
float lx = gmLum(texture2DCv(inputImg.texture, clamp(wuv + vec2(px.x * 2.0, 0.0), 0.0, 1.0)).rgb)
- gmLum(texture2DCv(inputImg.texture, clamp(wuv - vec2(px.x * 2.0, 0.0), 0.0, 1.0)).rgb);
float ly = gmLum(texture2DCv(inputImg.texture, clamp(wuv + vec2(0.0, px.y * 2.0), 0.0, 1.0)).rgb)
- gmLum(texture2DCv(inputImg.texture, clamp(wuv - vec2(0.0, px.y * 2.0), 0.0, 1.0)).rgb);
float edge = clamp(length(vec2(lx, ly)) * 6.0, 0.0, 1.0);
c *= 1.0 - edgeDark * edge * 0.55;
float grain = gmVnoise(uv * getTexSize(inputImg.size) * 0.35 * grainScale);
c += (grain - 0.5) * paperGrain * 0.22;
c = mix(c, vec3(1.0), paperLift * (0.4 + 0.6 * grain) * 0.35);
gl_FragColor = vec4(clamp(c, 0.0, 1.0) * src.a, src.a);
}
